package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"

	demopkg "github.com/alswl/humanirvana/tests/integration/huma"
	huma "github.com/danielgtaylor/huma/v2"
	"github.com/danielgtaylor/huma/v2/adapters/humago"
)

func main() {
	port := 8080
	if envPort := os.Getenv("PORT"); envPort != "" {
		fmt.Sscanf(envPort, "%d", &port)
	}

	// Create router and API
	router := http.NewServeMux()
	api := humago.New(router, huma.DefaultConfig("Demo API", "1.0.0"))

	// Register routes (these would be auto-generated by adapter in real migration)
	huma.Get(api, "/health", demopkg.Health)
	huma.Get(api, "/users", demopkg.ListUsers)
	huma.Post(api, "/users", demopkg.CreateUser)
	huma.Get(api, "/users/{id}", demopkg.GetUser)
	huma.Delete(api, "/users/{id}", func(ctx context.Context, input *struct {
		ID string `path:"id"`
	}) (*struct{}, error) {
		return nil, demopkg.DeleteUser(ctx, input)
	})

	log.Printf("Starting Huma demo server on port %d", port)

	server := &http.Server{
		Addr:    fmt.Sprintf(":%d", port),
		Handler: router,
	}

	// Start server in goroutine
	go func() {
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Printf("Server error: %v", err)
		}
	}()

	// Wait for interrupt signal
	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	log.Println("Shutting down server...")
	server.Shutdown(context.Background())
}
